#!/usr/bin/env perl
# ABOUTME: Debug script to isolate method call parsing issue
# ABOUTME: Tests progressively complex expressions to find where parsing breaks
use 5.42.0;
use FindBin qw($RealBin);
use lib "$RealBin/lib";

use Chalk::Grammar::Perl;
use Chalk::Parser;

my $parser = Chalk::Parser->new(grammar => $Chalk::Grammar::Perl::chalk_grammar);

my @test_cases = (
    # Simple cases
    'our $x = 1;',
    'our $x = Foo->new();',
    'our $x = Foo->new(a => 1);',
    'our $x = Foo->new(a => 1, b => 2);',

    # Array ref
    'our $x = [];',
    'our $x = [1];',
    'our $x = [1, 2];',

    # Hash ref
    'our $x = {};',
    'our $x = {a => 1};',

    # Method call with hash args
    'our $x = Foo->bar(a => 1);',
    'our $x = Foo->bar(rules => []);',
    'our $x = Foo->bar(rules => [1]);',
    'our $x = Foo->bar(a => 1, rules => []);',

    # The actual problematic pattern (simplified)
    'our $x = Foo->bar(a => [1], b => [2]);',
);

for my $test (@test_cases) {
    my $result = $parser->parse_string($test);
    my $status = $result ? "OK" : "FAIL";
    printf "%-8s: %s\n", $status, $test;
}

