#!/usr/bin/env perl
# ABOUTME: Debug script testing the actual Grammar/Perl.pm structure
# ABOUTME: Tests multiline method calls with complex nested structures
use 5.42.0;
use FindBin qw($RealBin);
use lib "$RealBin/lib";

use Chalk::Grammar::Perl;
use Chalk::Parser;

my $parser = Chalk::Parser->new(grammar => $Chalk::Grammar::Perl::chalk_grammar);

my @test_cases = (
    # Single line
    'our $x = Foo->bar(a => [1], b => [2]);',

    # Multi-line but simple
    'our $x = Foo->bar(
    a => [1]
);',

    # Multi-line with two args
    'our $x = Foo->bar(
    a => [1],
    b => [2]
);',

    # With nested arrayrefs
    'our $x = Foo->bar(
    a => [1, 2, 3],
    b => [4, 5, 6]
);',

    # Closer to actual structure
    'our $x = Foo->bar(
    a => [1],
    b => [
        [2, 3]
    ]
);',

    # The actual pattern from Grammar/Perl.pm (simplified)
    'our $chalk_grammar = Chalk::Grammar->build_grammar(
    auto_insert => [1],
    rules       => [
        [2, 3]
    ]
);',
);

for my $test (@test_cases) {
    my $result = $parser->parse_string($test);
    my $status = $result ? "OK" : "FAIL";
    my $preview = $test;
    $preview =~ s/\n/ /g;
    $preview = substr($preview, 0, 60) . "..." if length($preview) > 60;
    printf "%-8s: %s\n", $status, $preview;
}

