# ABOUTME: Test regex literals with escaped parentheses
# ABOUTME: Check if qr// with \( and \) causes parsing issues
use 5.42.0;
use FindBin qw($RealBin);
use lib "$RealBin/lib";

use Chalk::Grammar::Perl;
use Chalk::Parser;

my $parser = Chalk::Parser->new(grammar => $Chalk::Grammar::Perl::chalk_grammar);

my @test_cases = (
    # Simple regex with escaped parens
    q{my $re = qr/\(foo\)/;},

    # The actual problematic regex from line 149
    q{my $re = qr/\(\s*(?:\\\[[\$\@\%\&\*]+\s*\]|[\$\@\%\&\*\_;\s])*?\)/;},

    # In an array
    q{my $x = [qr/\(foo\)/];},

    # In a nested array (like grammar rules)
    q{my $x = [['X', qr/\(foo\)/]];},

    # Multiple rules with regex containing parens
    q{our $x = Foo->bar(
    rules => [
        ['A', qr/\(/],
        ['B', qr/\)/]
    ]
);},
);

for my $test (@test_cases) {
    my $result = $parser->parse_string($test);
    my $status = $result ? "OK" : "FAIL";
    my $preview = $test;
    $preview =~ s/\n/ /g;
    $preview = substr($preview, 0, 70) . "..." if length($preview) > 70;
    printf "%-8s: %s\n", $status, $preview;
}

