my $file = "$RealBin/lib/Chalk/Grammar/Perl.pm";
open my $fh, '<', $file or die $!;
my $source = do { local $/; <$fh> };
close $fh;

say "Original size: " . length($source);

my $preprocessor = Chalk::Preprocessor::Heredoc->new(input => $source);
