package Chalk::Grammar::BNF;
use 5.42.0;
use utf8;
use experimental qw(builtin);
use builtin qw(trim);

sub parse_bnf_file {
    my ($filename, $patterns_file) = @_;

    # Load patterns if provided
    my %patterns;
    if ($patterns_file) {
        %patterns = load_patterns($patterns_file);
    }

    open my $fh, '<:utf8', $filename or die "Cannot open $filename: $!";
    my @rules;

    while (my $line = <$fh>) {
        # Strip comments and whitespace
        $line =~ s/#.*$//;
        $line = trim($line);

        # Skip blank lines
        next if $line eq '';

        # Parse rule: LHS -> RHS
