     7→class Chalk::GrammarRule {
     8→
     9→    # Supports both exact token matching and lexeme/regex patterns for terminals
    10→    # Use parse() for pre-tokenized input, parse_string() for lexeme matching
    11→    #
    12→    # TODO: Consider matrix-based Earley parsing optimization
    13→    # See: https://medium.com/@celine.y.lee/fast-earley-parsing-2216fb0909a3
    14→    # Matrix operations could optimize prediction/completion phases while
    15→    # lexemes handle terminal matching independently
    16→    use overload '""' => 'to_string';
    17→
    18→    state $next_id = 0;    # auto-incrementing rule ID
    19→    field $id  :reader = $next_id++;
    20→    field $lhs :param :reader;
    21→    field $rhs :param :reader;
    22→    field $probability :param :reader = 1.0;
    23→    field $nullable;
    24→
    25→    method is_right_recursive() { $lhs eq $rhs->[-1] }
    26→    method is_left_recursive()  { $lhs eq $rhs->[0] }
    27→
    28→    method is_nullable( $grammar, $seen = {} ) {
    29→        return $nullable if defined($nullable);    # memoize nullable
    30→
    31→        # Empty production is nullable
    32→        return $nullable = 1 if @$rhs == 0;
    33→
    34→        # All symbols in RHS must be nullable
    35→        return $nullable = 1 if all {
    36→            my @rules = $grammar->rules_for($_);
    37→
    38→            # Terminals (no rules) are not nullable
    39→            return 0 unless @rules;
    40→
    41→            # In cycle, assume not nullable
    42→            return 0 if $seen->{$_};
    43→
    44→            # Check if this symbol is nullable via any of its rules
    45→            $seen->{$_} = 1;
    46→            return 0 unless any { $_->is_nullable( $grammar, $seen ) } @rules;
    47→        } @$rhs;
    48→
    49→        return $nullable = 0;
    50→    }
    51→
