#!/usr/bin/env perl
# ABOUTME: Compare BNF-loaded rules vs original rules
# ABOUTME: Debug why BNF grammar fails to parse
use 5.42.0;
use FindBin qw($RealBin);
use lib "$RealBin/lib";

use Chalk::Grammar::Perl;
use Chalk::Grammar::BNF;
use Chalk::Grammar;
use Data::Dumper;

# Load original grammar
my $orig_grammar = $Chalk::Grammar::Perl::chalk_grammar;
my $orig_rules = $orig_grammar->rules;

# Load BNF grammar
my $bnf_rules = Chalk::Grammar::BNF::parse_bnf_file("$RealBin/grammar/perl-full.bnf");

# Reorder BNF rules to have Program first
my @ordered_bnf = (
    grep { $_->[0] eq 'Program' } @$bnf_rules,
    grep { $_->[0] ne 'Program' } @$bnf_rules
);

my $bnf_grammar = Chalk::Grammar->build_grammar(rules => \@ordered_bnf);
my $bnf_rules_hash = $bnf_grammar->rules;

# Compare Program rules
say "=== Original Program rules ===";
for my $rule ($orig_rules->{Program}->@*) {
    say "  " . $rule->to_string;
}

say "\n=== BNF Program rules ===";
for my $rule ($bnf_rules_hash->{Program}->@*) {
    say "  " . $rule->to_string;
}

# Compare first few StatementList rules
say "\n=== Original StatementList rules (first 5) ===";
my @orig_sl = $orig_rules->{StatementList}->@*;
for my $i (0..4) {
    say "  " . $orig_sl[$i]->to_string if $orig_sl[$i];
}

say "\n=== BNF StatementList rules (first 5) ===";
my @bnf_sl = $bnf_rules_hash->{StatementList}->@*;
for my $i (0..4) {
    say "  " . $bnf_sl[$i]->to_string if $bnf_sl[$i];
}

# Check if 'my' is defined as a nonterminal or terminal
say "\n=== Checking 'my' symbol ===";
say "Original: 'my' is " . ($orig_grammar->is_nonterminal('my') ? "nonterminal" : "terminal");
say "BNF:      'my' is " . ($bnf_grammar->is_nonterminal('my') ? "nonterminal" : "terminal");

# Check VariableDecl rules
say "\n=== Original VariableDecl rules (first 3) ===";
my @orig_vd = $orig_rules->{VariableDecl}->@*;
for my $i (0..2) {
    if ($orig_vd[$i]) {
        my $rule = $orig_vd[$i];
        say "  " . $rule->to_string;
        say "    RHS: " . join(', ', map { ref($_) ? "REGEX" : "'$_'" } $rule->rhs->@*);
    }
}

say "\n=== BNF VariableDecl rules (first 3) ===";
my @bnf_vd = $bnf_rules_hash->{VariableDecl}->@*;
for my $i (0..2) {
    if ($bnf_vd[$i]) {
        my $rule = $bnf_vd[$i];
        say "  " . $rule->to_string;
        say "    RHS: " . join(', ', map { ref($_) ? "REGEX" : "'$_'" } $rule->rhs->@*);
    }
}

