#!/usr/bin/env perl
# ABOUTME: Test loading grammar from BNF file
# ABOUTME: Verifies the BNF format can replace the arrayref structure
use 5.42.0;
use FindBin qw($RealBin);
use lib "$RealBin/lib";

use Chalk::Grammar::BNF;
use Chalk::Grammar;
use Chalk::Parser;

say "Loading grammar from BNF file...";
my $rules = Chalk::Grammar::BNF::parse_bnf_file("$RealBin/grammar/perl-full.bnf");
say "Loaded " . scalar(@$rules) . " rules";

say "\nBuilding grammar object...";
# The first rule should be Program, but make sure by prepending it
my @ordered_rules = (
    grep { $_->[0] eq 'Program' } @$rules,
    grep { $_->[0] ne 'Program' } @$rules
);

# Don't auto-insert WS_OPT - the BNF file already has it inserted
my $grammar = Chalk::Grammar->build_grammar(
    rules       => \@ordered_rules
);

say "Grammar built successfully!";
say "Start symbol: " . $grammar->start_symbol;

# Test a simple parse
say "\nTesting simple parse...";
my $parser = Chalk::Parser->new(grammar => $grammar);
my $test_code = 'my $x = 1;';
my $result = $parser->parse_string($test_code);

if ($result) {
    say "OK: Successfully parsed: $test_code";
} else {
    say "FAIL: Failed to parse: $test_code";
}

