     1→# ABOUTME: Simple BNF file parser for loading grammar rules
     2→# ABOUTME: Avoids complex nested structures for bootstrap self-hosting
     3→package Chalk::Grammar::BNF;
     4→use 5.42.0;
     5→use utf8;
     6→
     7→sub parse_bnf_file {
     8→    my ($filename) = @_;
     9→
    10→    open my $fh, '<:utf8', $filename or die "Cannot open $filename: $!";
    11→    my %patterns;
    12→    my @rules;
    13→
    14→    while (my $line = <$fh>) {
    15→        $line = trim($line);
    16→
    17→        # Skip blank lines
    18→        next if $line eq '';
    19→
    20→        # Pattern definition: %NAME% = /regex/flags
    21→        # Must match before comment stripping since patterns may contain #
    22→        if ($line =~ /^%(\w+)%\s*=\s*\/(.+)\/([a-z]*)/) {
    23→            my ($name, $pattern, $flags) = ($1, $2, $3 || '');
    24→            $patterns{$name} = qr/(?$flags:$pattern)/;
    25→            next;
    26→        }
    27→
    28→        # Strip comments AFTER checking for pattern definitions
    29→        $line =~ s/#.*$//;
    30→        $line = trim($line);
    31→        next if $line eq '';
    32→
    33→        # Grammar rule: LHS -> RHS
    34→        if ($line =~ /^(\w+)\s*->\s*(.*)$/) {
    35→            my ($lhs, $rhs) = ($1, $2);
    36→
    37→            # Empty RHS means epsilon rule
    38→            if ($rhs eq '') {
    39→                push @rules, [$lhs => []];
    40→                next;
    41→            }
    42→
    43→            # Parse RHS tokens
    44→            my @rhs_tokens = parse_rhs($rhs, \%patterns);
    45→            push @rules, [$lhs => \@rhs_tokens];
    46→        }
    47→        else {
    48→            die "Invalid BNF syntax at line $.: $line\n";
    49→        }
    50→    }
    51→
    52→    close $fh;
    53→    return \@rules;
    54→}
    55→
    56→sub parse_rhs {
    57→    my ($rhs, $patterns) = @_;
    58→    my @tokens;
    59→
    60→    # Tokenize RHS, handling quoted strings and regexes
    61→    while ($rhs =~ /\S/) {
    62→        $rhs = trim($rhs);
    63→
    64→        # Single-quoted string (terminal)
    65→        if ($rhs =~ /^'([^']*)'/) {
    66→            push @tokens, $1;
    67→            $rhs = substr($rhs, length($&));
    68→        }
    69→        # Pattern reference %NAME%
    70→        elsif ($rhs =~ /^%(\w+)%/) {
    71→            my $pattern_name = $1;
    72→            if (exists $patterns->{$pattern_name}) {
    73→                push @tokens, $patterns->{$pattern_name};
    74→            }
    75→            else {
    76→                die "Undefined pattern: $pattern_name\n";
    77→            }
