        ['PatternRef' => [qr/%(\w+)%/]],
        ['Identifier' => [qr/([a-zA-Z_][\w:]*)/]],

        ['Comment' => [qr/#.*$/m]],
        ['BlankLine' => [qr/^\s*$/m]],

        # Whitespace - BNF files are line-based
        ['WS_OPT' => []],
        ['WS_OPT' => ['WS']],
        ['WS' => [qr/[ \t]+/]],
