    my ($rhs_node, $patterns) = @_;
    my @tokens;

    return @tokens unless ref($rhs_node) eq 'ARRAY';

    my ($type, @children) = @$rhs_node;

    if ($type eq 'RHS') {
        if (@children && ref($children[0]) eq 'ARRAY') {
