    my @tokens;

    return @tokens unless ref($token_list_node) eq 'ARRAY';

    my ($type, @children) = @$token_list_node;

    if ($type eq 'TokenList') {
        # First child is Token, second (if exists) is TokenList
        if (@children && ref($children[0]) eq 'ARRAY') {
            my $token = extract_token($children[0], $patterns);
            push @tokens, $token if defined $token;

            # Recursively get rest of tokens
            if (@children > 1 && ref($children[1]) eq 'ARRAY') {
                push @tokens, extract_token_list($children[1], $patterns);
            }
        }
    }

    return @tokens;
}

sub extract_token {
    my ($token_node, $patterns) = @_;

    return unless ref($token_node) eq 'ARRAY';

    my ($type, @children) = @$token_node;

    if ($type eq 'Token' && @children) {
        my $child = $children[0];
        return unless ref($child) eq 'ARRAY';

        my ($child_type, $value) = @$child;

        if ($child_type eq 'Terminal') {
