# ABOUTME: Semiring that builds a Chalk::Grammar directly while parsing BNF
# ABOUTME: Demonstrates using semiring operations to construct the parse result
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use Chalk::Base;
use Chalk::Grammar;

class Chalk::Semiring::ChalkGrammarElement :isa(Chalk::Element) {
    field $patterns :param = {};      # Pattern definitions: %NAME% => qr//
    field $rules :param = [];         # Grammar rules: [LHS => [RHS]]
    field $tokens :param = [];        # Current RHS tokens being built
    field $lhs :param = undef;        # Current LHS nonterminal
    field $terminal :param = undef;   # Matched terminal value
    field $pattern_name :param = undef;   # Pattern name for definitions
    field $pattern_regex :param = undef;  # Pattern regex for definitions

    method add($other, $swap = undef) {
        # OR operation: combine alternatives
        # Merge patterns and rules from both branches
        my %combined_patterns = ($patterns->%*, $other->patterns->%*);
        my @combined_rules = ($rules->@*, $other->rules->@*);

        return Chalk::Semiring::ChalkGrammarElement->new(
            patterns => \%combined_patterns,
            rules => \@combined_rules,
        );
    }

    method multiply($other, $swap = undef) {
        # AND operation: sequential combination
        # Right element's data takes precedence for building up current rule
        my %combined_patterns = ($patterns->%*, $other->patterns->%*);
        my @combined_rules = ($rules->@*, $other->rules->@*);
        my @combined_tokens = ($tokens->@*, $other->tokens->@*);

        # If other has LHS, use it (building a complete rule)
        my $result_lhs = $other->lhs // $lhs;

        # If other has a terminal or pattern ref, add to tokens
        if (defined $other->terminal) {
            push @combined_tokens, $other->terminal;
        }

        # Check if we have a complete pattern definition
        my $result_pattern_name = $other->pattern_name // $pattern_name;
        my $result_pattern_regex = $other->pattern_regex // $pattern_regex;

        if (defined $result_pattern_name && defined $result_pattern_regex) {
            $combined_patterns{$result_pattern_name} = $result_pattern_regex;
        }

        return Chalk::Semiring::ChalkGrammarElement->new(
            patterns => \%combined_patterns,
            rules => \@combined_rules,
            tokens => \@combined_tokens,
            lhs => $result_lhs,
            terminal => $other->terminal,
            pattern_name => $result_pattern_name,
            pattern_regex => $result_pattern_regex,
        );
    }

    method equals($other, $swap = undef) {
        return 0 unless ref($other) eq ref($self);
        # For now, simple reference equality
        return $self == $other;
    }

    method score() {
        return 1;  # Always valid if parse succeeds
    }

    method to_string(@) {
        return sprintf("Grammar[%d patterns, %d rules]",
            scalar(keys $patterns->%*),
            scalar($rules->@*));
    }

    # Accessors for extracting final grammar
    method get_patterns() { return $patterns; }
    method get_rules() { return $rules; }
    method get_tokens() { return $tokens; }
    method get_lhs() { return $lhs; }
}

class Chalk::Semiring::ChalkGrammar :isa(Chalk::Semiring) {
    field $mul_id :reader = Chalk::Semiring::ChalkGrammarElement->new();
    field $add_id :reader = Chalk::Semiring::ChalkGrammarElement->new();

    # Pattern storage shared across all elements during parse
    field %patterns;

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0) {
        my $lhs = $rule->lhs;
        my $rhs = $rule->rhs;

        # Extract the actual matched text for terminals
        # This is a bit tricky - we need access to the input string
        # For now, we'll handle this specially for regex captures

        if ($lhs eq 'PatternName') {
            # This is %PATTERN_NAME%
            my $pattern = $rhs->[0];
            if (ref($pattern) eq 'Regexp' && $pattern =~ /^%(\w+)%$/) {
                return Chalk::Semiring::ChalkGrammarElement->new(
                    pattern_name => $1
                );
            }
        }
        elsif ($lhs eq 'RegexLiteral') {
            # This is /pattern/flags
            # The regex will capture the pattern and flags
            return Chalk::Semiring::ChalkGrammarElement->new();
        }
        elsif ($lhs eq 'Terminal') {
            # This is 'string'
            return Chalk::Semiring::ChalkGrammarElement->new();
        }
        elsif ($lhs eq 'Identifier') {
            # This is a nonterminal name
            return Chalk::Semiring::ChalkGrammarElement->new();
        }
        elsif ($lhs eq 'PatternRef') {
            # This is %PATTERN_N%
            return Chalk::Semiring::ChalkGrammarElement->new();
        }
        elsif ($lhs eq 'GrammarRule') {
            # Complete rule: LHS -> RHS
            return Chalk::Semiring::ChalkGrammarElement->new();
        }

        # Default: empty element
        return Chalk::Semiring::ChalkGrammarElement->new();
    }

    method multiply($x, $y) {
        return $x->multiply($y);
    }

    method plus($x, $y) {
        return $x->add($y);
    }
}

1;

