# ABOUTME: Semiring that builds grammar data directly while parsing BNF
# ABOUTME: Uses matched_text parameter to extract terminals during parsing
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use Chalk::Base;

class Chalk::Semiring::ChalkGrammarElement :isa(Chalk::Element) {
    field $patterns :param = {};      # Pattern definitions: %NAME% => qr//
    field $rules :param = [];         # Grammar rules: [LHS => [RHS]]
    field $tokens :param = [];        # Current RHS tokens being built
    field $lhs :param = undef;        # Current LHS nonterminal
    field $terminal :param = undef;   # Matched terminal value
    field $pattern_name :param = undef;   # Pattern name for definitions
    field $pattern_body :param = undef;   # Pattern regex body
    field $pattern_flags :param = undef;  # Pattern regex flags

    method add($other, $swap = undef) {
        # OR operation: combine alternatives
        # Merge patterns and rules from both branches
        my %combined_patterns = ($patterns->%*, $other->patterns->%*);
        my @combined_rules = ($rules->@*, $other->rules->@*);

        return Chalk::Semiring::ChalkGrammarElement->new(
            patterns => \%combined_patterns,
            rules => \@combined_rules,
        );
    }

    method multiply($other, $swap = undef) {
        # AND operation: sequential combination
        # Right element's data takes precedence for building up current rule
        my %combined_patterns = ($patterns->%*, $other->patterns->%*);
        my @combined_rules = ($rules->@*, $other->rules->@*);
        my @combined_tokens = ($tokens->@*, $other->tokens->@*);

        # If other has LHS, use it (building a complete rule)
        my $result_lhs = $other->lhs // $lhs;

        # If other has a terminal, add to tokens
        if (defined $other->terminal) {
            push @combined_tokens, $other->terminal;
        }

        # Build pattern definitions
        my $result_pattern_name = $other->pattern_name // $pattern_name;
        my $result_pattern_body = $other->pattern_body // $pattern_body;
        my $result_pattern_flags = $other->pattern_flags // $pattern_flags;

        # If we have complete pattern definition, compile and store it
        if (defined $result_pattern_name && defined $result_pattern_body) {
            my $flags = $result_pattern_flags // '';
            $combined_patterns{$result_pattern_name} = qr/(?$flags:$result_pattern_body)/;
        }

        # Build grammar rules
        if (defined $result_lhs && @combined_tokens && !defined $other->lhs) {
            # We have a complete rule: LHS and all RHS tokens
            push @combined_rules, [$result_lhs => [@combined_tokens]];
            # Reset for next rule
            @combined_tokens = ();
            $result_lhs = undef;
        }

        return Chalk::Semiring::ChalkGrammarElement->new(
            patterns => \%combined_patterns,
            rules => \@combined_rules,
            tokens => \@combined_tokens,
            lhs => $result_lhs,
            terminal => $other->terminal,
            pattern_name => $result_pattern_name,
            pattern_body => $result_pattern_body,
            pattern_flags => $result_pattern_flags,
        );
    }

    method equals($other, $swap = undef) {
        return 0 unless ref($other) eq ref($self);
        # For now, simple reference equality
        return $self == $other;
    }

    method score() {
        return 1;  # Always valid if parse succeeds
    }

    method to_string(@) {
        return sprintf("Grammar[%d patterns, %d rules]",
            scalar(keys $patterns->%*),
            scalar($rules->@*));
    }

    # Accessors for extracting final grammar
    method get_patterns() { return $patterns; }
    method get_rules() { return $rules; }
    method get_tokens() { return $tokens; }
    method get_lhs() { return $lhs; }
}

class Chalk::Semiring::ChalkGrammar :isa(Chalk::Semiring) {
    field $mul_id :reader = Chalk::Semiring::ChalkGrammarElement->new();
    field $add_id :reader = Chalk::Semiring::ChalkGrammarElement->new();

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0, $matched_text = undef) {
        my $lhs = $rule->lhs;

        # Extract captured groups from matched text based on rule type
        if (defined $matched_text && $lhs eq 'PatternName') {
            # %PATTERN_NAME% - extract PATTERN_NAME
            if ($matched_text =~ /^%(\w+)%$/) {
                return Chalk::Semiring::ChalkGrammarElement->new(
                    pattern_name => $1
                );
            }
        }
        elsif (defined $matched_text && $lhs eq 'RegexLiteral') {
            # /pattern/flags - extract pattern and flags
            if ($matched_text =~ m{^/((?:[^\\/]|\\.)*)/(\w*)$}) {
                return Chalk::Semiring::ChalkGrammarElement->new(
                    pattern_body => $1,
                    pattern_flags => $2
                );
            }
        }
        elsif (defined $matched_text && $lhs eq 'Terminal') {
            # 'string' - extract string value
            if ($matched_text =~ /^'([^']*)'$/) {
                return Chalk::Semiring::ChalkGrammarElement->new(
                    terminal => $1
                );
            }
        }
        elsif (defined $matched_text && $lhs eq 'PatternRef') {
            # %PATTERN_N% - this becomes a pattern reference in the RHS
            if ($matched_text =~ /^%(\w+)%$/) {
                # We'll need to look up the pattern later
                return Chalk::Semiring::ChalkGrammarElement->new(
                    terminal => "%$1%"  # Store as marker
                );
            }
        }
        elsif (defined $matched_text && $lhs eq 'Identifier') {
            # Nonterminal name or LHS
            return Chalk::Semiring::ChalkGrammarElement->new(
                lhs => $matched_text
            );
        }

        # Default: empty element for non-terminals and structural nodes
        return Chalk::Semiring::ChalkGrammarElement->new();
    }

    method multiply($x, $y) {
        return $x->multiply($y);
    }

    method plus($x, $y) {
        return $x->add($y);
    }
}

1;

