    auto_insert => ['WS_OPT'],
    rules => [
        # Top level: file contains lines
        ['BNFFile' => ['LineList']],

        ['LineList' => []],  # Empty file
        ['LineList' => ['Line', 'LineList']],

        ['Line' => ['PatternDef']],
        ['Line' => ['GrammarRule']],
        ['Line' => ['Comment']],

        # Pattern definition: %NAME% = /pattern/flags
        ['PatternDef' => ['PatternName', '=', 'RegexLiteral']],
        ['PatternName' => [qr/%(\w+)%/]],
        # Match /pattern/flags where pattern can contain \/ or any non-/
        ['RegexLiteral' => [qr{/((?:[^\\/]|\\.)*)/([\w]*)}]],

        # Grammar rule: LHS -> RHS
        ['GrammarRule' => ['Identifier', '->', 'RHS']],
        ['RHS' => ['TokenList']],
        ['RHS' => []],  # Empty RHS (epsilon rule)

        ['TokenList' => ['Token']],
        ['TokenList' => ['Token', 'TokenList']],

        ['Token' => ['Terminal']],
        ['Token' => ['PatternRef']],
        ['Token' => ['Identifier']],

        ['Terminal' => [qr/'([^']*)'/]],
        ['PatternRef' => [qr/%(\w+)%/]],
        ['Identifier' => [qr/([a-zA-Z_][\w:]*)/]],

        ['Comment' => [qr/#[^\n]*/]],

        # Whitespace handling
        ['WS_OPT' => []],
        ['WS_OPT' => ['WS']],
        ['WS_OPT' => ['WS', 'WS_OPT']],
        ['WS' => [qr/[ \t\n]+/]],
