my $parser = Chalk::Parser->new(
    grammar => $bnf_grammar,
    semiring => $semiring
);
my $parse_result = $parser->parse_string($content);

if ($parse_result) {
    say "Parse tree:";
    say Dumper($parse_result->tree);
} else {
    say "Parse failed!";
}
