# ABOUTME: Simple array-based parse tree semiring with matched text storage
# ABOUTME: Stores terminals with their matched text for post-processing extraction
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use Chalk::Base;

class Chalk::Semiring::ArrayTreeElement :isa(Chalk::Element) {
    field $tree :param :reader;  # Array tree: [$lhs, @children]

    method add($other, $swap = undef) {
        # OR operation: take best alternative
        # If self is add_id (⊥), return other
        # Otherwise return self (first parse wins)
        return $other if $tree->[0] eq '⊥';
        return $self;
    }

    method multiply($other, $swap = undef) {
        # Sequence: append child to tree
        my @new_tree = $tree->@*;
        push @new_tree, $other->tree;

        return Chalk::Semiring::ArrayTreeElement->new(
            tree => \@new_tree
        );
    }

    method equals($other, $swap = undef) {
        return 0 unless ref($other) eq ref($self);
        return builtin::refaddr($tree) == builtin::refaddr($other->tree);
    }

    method score() {
        return 1;
    }

    method to_string(@) {
        return Chalk::Semiring::ArrayTree::_tree_to_string($tree);
    }
}

# Helper function for tree stringification
sub Chalk::Semiring::ArrayTree::_tree_to_string {
    my ($tree) = @_;
    return '[]' unless ref($tree) eq 'ARRAY';

    my ($lhs, @children) = $tree->@*;
    return $lhs unless @children;

    my $children_str = join(', ', map { Chalk::Semiring::ArrayTree::_tree_to_string($_) } @children);
    return "[$lhs: $children_str]";
}

class Chalk::Semiring::ArrayTree :isa(Chalk::Semiring) {
    field $mul_id :reader = Chalk::Semiring::ArrayTreeElement->new(tree => ['ε']);
    field $add_id :reader = Chalk::Semiring::ArrayTreeElement->new(tree => ['⊥']);

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0, $matched_text = undef) {
        my $lhs = $rule->lhs;

        # If we have matched text, store it as the only child
        # This preserves the terminal's matched text for extraction
        if (defined $matched_text) {
            return Chalk::Semiring::ArrayTreeElement->new(
                tree => [$lhs, $matched_text]
            );
        }

        # Non-terminal: just LHS, children added via multiply
        return Chalk::Semiring::ArrayTreeElement->new(
            tree => [$lhs]
        );
    }

    method multiply($x, $y) {
        return $x->multiply($y);
    }

    method plus($x, $y) {
        return $x->add($y);
    }
}

