# ABOUTME: BNF file parser using Earley parser with hand-coded minimal grammar
# ABOUTME: Demonstrates Chalk parsing its own grammar format for bootstrap
package Chalk::Grammar::BNF;
use 5.42.0;
use utf8;
use Chalk::Grammar;
use Chalk::Parser;
use Chalk::Semiring::ArrayTree;

# Minimal hand-coded grammar for parsing BNF files
# This breaks the bootstrap cycle: BNF grammar is hand-coded,
# then used to parse the full Perl grammar from BNF file
my $bnf_grammar = Chalk::Grammar->build_grammar(
    auto_insert => ['WS_OPT'],
    rules => [
        # Top level: file contains lines
        ['BNFFile' => ['LineList']],

        ['LineList' => []],  # Empty file
        ['LineList' => ['Line', 'LineList']],

        ['Line' => ['PatternDef']],
        ['Line' => ['GrammarRule']],
        ['Line' => ['Comment']],

        # Pattern definition: %NAME% = /pattern/flags
        ['PatternDef' => ['PatternName', '=', 'RegexLiteral']],
        ['PatternName' => [qr/%(\w+)%/]],
        # Match /pattern/flags where pattern can contain \/ or any non-/
        ['RegexLiteral' => [qr{/((?:[^\\/]|\\.)*)/([\w]*)}]],

        # Grammar rule: LHS -> RHS
        ['GrammarRule' => ['Identifier', '->', 'RHS']],
        ['RHS' => ['TokenList']],
        ['RHS' => []],  # Empty RHS (epsilon rule)

        ['TokenList' => ['Token']],
        ['TokenList' => ['Token', 'TokenList']],

        ['Token' => ['Terminal']],
        ['Token' => ['PatternRef']],
        ['Token' => ['Identifier']],

        ['Terminal' => [qr/'([^']*)'/]],
        ['PatternRef' => [qr/%(\w+)%/]],
        ['Identifier' => [qr/([a-zA-Z_][\w:]*)/]],

        ['Comment' => [qr/#[^\n]*/]],

        # Whitespace handling
        ['WS_OPT' => []],
        ['WS_OPT' => ['WS']],
        ['WS_OPT' => ['WS', 'WS_OPT']],
        ['WS' => [qr/[ \t\n]+/]],
    ]
);

sub parse_bnf_file {
    my ($filename) = @_;

    open my $fh, '<:utf8', $filename or die "Cannot open $filename: $!";
    my $content = do { local $/; <$fh> };
    close $fh;

    # Use ArrayTree semiring to build parse tree with matched text
    my $semiring = Chalk::Semiring::ArrayTree->new();
    my $parser = Chalk::Parser->new(
        grammar => $bnf_grammar,
        semiring => $semiring
    );
    my $parse_result = $parser->parse_string($content);

    unless ($parse_result) {
        die "Failed to parse BNF file: $filename\n";
    }

    # Extract patterns and rules from parse tree
    # Matched text is now stored in the tree, no need to re-parse
    my %patterns;
    my @rules;

    my $tree = $parse_result->tree;
    extract_bnf_data($tree, \%patterns, \@rules);

    return \@rules;
}

sub extract_bnf_data {
    my ($node, $patterns, $rules) = @_;

    return unless ref($node) eq 'ARRAY';

    my ($type, @children) = @$node;

    if ($type eq 'PatternDef') {
        # Extract pattern name and regex
        # children[0] = PatternName node with matched text
        # children[1] = '=' terminal
        # children[2] = RegexLiteral node with matched text
        my $name_node = $children[0];
        my $regex_node = $children[2];

        if (ref($name_node) eq 'ARRAY' && $name_node->[0] eq 'PatternName') {
            # Matched text is stored as child[1] by ArrayTree semiring
            my $name_text = $name_node->[1];
            if ($name_text =~ /^%(\w+)%$/) {
                my $name = $1;

                if (ref($regex_node) eq 'ARRAY' && $regex_node->[0] eq 'RegexLiteral') {
                    my $regex_text = $regex_node->[1];
                    if ($regex_text =~ m{^/((?:[^\\/]|\\.)*)/([\w]*)$}) {
                        my ($pattern, $flags) = ($1, $2 // '');
                        $patterns->{$name} = qr/(?$flags:$pattern)/;
                    }
                }
            }
        }
    }
    elsif ($type eq 'GrammarRule') {
        # Extract LHS and RHS
        my $lhs_node = $children[0];
        my $rhs_node = $children[2];

        if (ref($lhs_node) eq 'ARRAY' && $lhs_node->[0] eq 'Identifier') {
            # Matched text is stored as child[1]
            my $lhs = $lhs_node->[1];
            my @rhs_tokens;

            if (ref($rhs_node) eq 'ARRAY' && $rhs_node->[0] eq 'RHS') {
                @rhs_tokens = extract_rhs_tokens($rhs_node, $patterns);
            }

            push @$rules, [$lhs => \@rhs_tokens];
        }
    }

    # Recursively process children
    for my $child (@children) {
        extract_bnf_data($child, $patterns, $rules);
    }
}

sub extract_rhs_tokens {
    my ($rhs_node, $patterns) = @_;
    my @tokens;

    return @tokens unless ref($rhs_node) eq 'ARRAY';

    my ($type, @children) = @$rhs_node;

    if ($type eq 'RHS') {
        if (@children && ref($children[0]) eq 'ARRAY') {
            @tokens = extract_token_list($children[0], $patterns);
        }
    }

    return @tokens;
}

sub extract_token_list {
    my ($token_list_node, $patterns) = @_;
    my @tokens;

    return @tokens unless ref($token_list_node) eq 'ARRAY';

    my ($type, @children) = @$token_list_node;

    if ($type eq 'TokenList') {
        # First child is Token, second (if exists) is TokenList
        if (@children && ref($children[0]) eq 'ARRAY') {
            my $token = extract_token($children[0], $patterns);
            push @tokens, $token if defined $token;

            # Recursively get rest of tokens
            if (@children > 1 && ref($children[1]) eq 'ARRAY') {
                push @tokens, extract_token_list($children[1], $patterns);
            }
        }
    }

    return @tokens;
}

sub extract_token {
    my ($token_node, $patterns) = @_;

    return unless ref($token_node) eq 'ARRAY';

    my ($type, @children) = @$token_node;

    if ($type eq 'Token' && @children) {
        my $child = $children[0];
        return unless ref($child) eq 'ARRAY';

        my ($child_type, $matched_text) = @$child;

        if ($child_type eq 'Terminal') {
            # Matched text is 'value' - extract value from quotes
            if ($matched_text =~ /^'([^']*)'$/) {
                return $1;
            }
        }
        elsif ($child_type eq 'PatternRef') {
            # Matched text is %NAME% - extract NAME and look up pattern
            if ($matched_text =~ /^%(\w+)%$/) {
                my $name = $1;
                return $patterns->{$name} if exists $patterns->{$name};
                die "Undefined pattern: $name\n";
            }
        }
        elsif ($child_type eq 'Identifier') {
            # Matched text is the identifier itself
            return $matched_text;
        }
    }

    return;
}

