# ABOUTME: Semiring for building grammar rules while parsing BNF files
# ABOUTME: Accumulates patterns and rules, resolves pattern references to regex objects
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use Chalk::Base;

class Chalk::Semiring::GrammarBuilderElement :isa(Chalk::Element) {
    field $patterns :param = {};    # Pattern name => compiled regex
    field $rules :param = [];       # [LHS => [RHS tokens]]

    # Current rule being built
    field $lhs :param = undef;
    field $rhs_tokens :param = [];

    # Current pattern being built
    field $pattern_name :param = undef;
    field $pattern_body :param = undef;
    field $pattern_flags :param = undef;

    method add($other, $swap = undef) {
        # OR operation: merge alternatives
        # Take patterns and rules from both branches
        my %combined_patterns = ($patterns->%*, $other->patterns->%*);
        my @combined_rules = ($rules->@*, $other->rules->@*);

        return Chalk::Semiring::GrammarBuilderElement->new(
            patterns => \%combined_patterns,
            rules => \@combined_rules,
        );
    }

    method multiply($other, $swap = undef) {
        # AND operation: sequential composition
        my %combined_patterns = ($patterns->%*, $other->patterns->%*);
        my @combined_rules = ($rules->@*, $other->rules->@*);
        my @combined_rhs = ($rhs_tokens->@*, $other->rhs_tokens->@*);

        # Accumulate LHS (rightmost wins for complete rules)
        my $result_lhs = $other->lhs // $lhs;

        # Accumulate pattern parts
        my $result_pattern_name = $other->pattern_name // $pattern_name;
        my $result_pattern_body = $other->pattern_body // $pattern_body;
        my $result_pattern_flags = $other->pattern_flags // $pattern_flags;

        # Complete pattern definition: compile and store
        if (defined $result_pattern_name && defined $result_pattern_body) {
            my $flags = $result_pattern_flags // '';
            $combined_patterns{$result_pattern_name} = qr/(?$flags:$result_pattern_body)/;
        }

        return Chalk::Semiring::GrammarBuilderElement->new(
            patterns => \%combined_patterns,
            rules => \@combined_rules,
            lhs => $result_lhs,
            rhs_tokens => \@combined_rhs,
            pattern_name => $result_pattern_name,
            pattern_body => $result_pattern_body,
            pattern_flags => $result_pattern_flags,
        );
    }

    method equals($other, $swap = undef) {
        return 0 unless ref($other) eq ref($self);
        # Simple reference equality
        return $self == $other;
    }

    method score() {
        return 1;
    }

    method to_string(@) {
        return sprintf("GrammarBuilder[%d patterns, %d rules]",
            scalar(keys $patterns->%*),
            scalar($rules->@*));
    }

    # Extract final results
    method get_patterns() { return $patterns; }
    method get_rules() { return $rules; }
}

class Chalk::Semiring::GrammarBuilder :isa(Chalk::Semiring) {
    field $mul_id :reader = Chalk::Semiring::GrammarBuilderElement->new();
    field $add_id :reader = Chalk::Semiring::GrammarBuilderElement->new();

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0, $matched_text = undef) {
        my $lhs = $rule->lhs;

        # Handle matched terminals and extract their values
        if (defined $matched_text) {
            if ($lhs eq 'PatternName') {
                # %PATTERN_NAME% - extract just the name
                if ($matched_text =~ /^%(\w+)%$/) {
                    return Chalk::Semiring::GrammarBuilderElement->new(
                        pattern_name => $1
                    );
                }
            }
            elsif ($lhs eq 'RegexLiteral') {
                # /pattern/flags - extract pattern and flags
                if ($matched_text =~ m{^/((?:[^\\/]|\\.)*)/([\w]*)$}) {
                    return Chalk::Semiring::GrammarBuilderElement->new(
                        pattern_body => $1,
                        pattern_flags => $2
                    );
                }
            }
            elsif ($lhs eq 'Terminal') {
                # 'value' - extract value without quotes, add to RHS
                if ($matched_text =~ /^'([^']*)'$/) {
                    return Chalk::Semiring::GrammarBuilderElement->new(
                        rhs_tokens => [$1]
                    );
                }
            }
            elsif ($lhs eq 'PatternRef') {
                # %NAME% - mark as pattern reference (will be resolved later)
                if ($matched_text =~ /^%(\w+)%$/) {
                    return Chalk::Semiring::GrammarBuilderElement->new(
                        rhs_tokens => ["%$1%"]  # Store marker for later resolution
                    );
                }
            }
            elsif ($lhs eq 'Identifier') {
                # Could be LHS or RHS nonterminal - context determines usage
                return Chalk::Semiring::GrammarBuilderElement->new(
                    lhs => $matched_text,
                    rhs_tokens => [$matched_text]
                );
            }
        }

        # Non-terminal rules: return empty element
        return Chalk::Semiring::GrammarBuilderElement->new();
    }
}

1;

