    # Semantic action: called when PatternDef rule completes
    # PatternDef -> PatternName '=' RegexLiteral
    method from_children($pattern_name_elem, $equals_elem, $regex_literal_elem) {
        # Extract pattern name from PatternName element
        my $name = $pattern_name_elem->name;

        # Extract pattern body and flags from RegexLiteral element
        my $body = $regex_literal_elem->body;
        my $flags = $regex_literal_elem->flags // '';

        # Compile the pattern
        my $compiled = qr/(?$flags:$body)/;

        return Chalk::BNF::PatternDef->new(
            name => $name,
            pattern => $compiled
        );
    }
}

