use 5.42.0;
use experimental qw(class);
use utf8;

class Chalk::BNF::RHS {
    field $tokens :param :reader = [];

    # Called when RHS completes
    # RHS -> TokenList
    # RHS -> (empty)
    sub from_element {
        my (, ) = ;
        my $children = $element->value;

        # Empty RHS
        return Chalk::BNF::RHS->new(tokens => []) unless defined $children;

        # Extract tokens from TokenList
        my @tokens;
        if (ref($children) && $children->can('tokens')) {
            @tokens = $children->tokens;
        } elsif (ref($children) eq 'ARRAY') {
            # Flatten token list
            @tokens = _flatten_tokens($children);
        }

        return Chalk::BNF::RHS->new(tokens => \@tokens);
    }
}

sub _flatten_tokens {
    my ($val) = @_;
