# ABOUTME: Semantic handler for top-level BNF file
# ABOUTME: Collects all pattern definitions and grammar rules
use 5.42.0;
use experimental qw(class);
use utf8;

class Chalk::BNF::BNFFile {
    field $patterns :param :reader = {};
    field $rules :param :reader = [];

    # Called when BNFFile completes
    # BNFFile -> LineList
    sub from_element {
        my ($class, $element) = @_;
        my $children = $element->value;

        my %patterns;
        my @rules;

        # Extract patterns and rules from LineList
        Chalk::BNF::BNFFile::_extract_items($children, \%patterns, \@rules);

        return Chalk::BNF::BNFFile->new(
            patterns => \%patterns,
            rules => \@rules
        );
    }

    # Get rules in format for Chalk::Grammar::build_grammar
    method get_rules() {
        # Resolve pattern references in rules
        my @resolved_rules;
        for my $rule (@$rules) {
            my ($lhs, $rhs) = @$rule;
            my @resolved_rhs;

            for my $token (@$rhs) {
                # Pattern reference: %NAME%
                if (!ref($token) && $token =~ /^%(\w+)%$/) {
                    my $pattern_name = $1;
                    if (exists $patterns->{$pattern_name}) {
                        push @resolved_rhs, $patterns->{$pattern_name};
                    } else {
                        die "Undefined pattern: $pattern_name\n";
                    }
                } else {
                    push @resolved_rhs, $token;
                }
            }

            push @resolved_rules, [$lhs, \@resolved_rhs];
        }

        return \@resolved_rules;
    }
}

package Chalk::BNF::BNFFile {
sub _extract_items {
    my ($val, $patterns, $rules) = @_;

    if (ref($val) eq 'ARRAY') {
        for my $item (@$val) {
            Chalk::BNF::BNFFile::_extract_items($item, $patterns, $rules);
        }
    } elsif (ref($val) && $val->isa('Chalk::BNF::PatternDef')) {
        $patterns->{$val->name} = $val->pattern;
    } elsif (ref($val) && $val->isa('Chalk::BNF::GrammarRule')) {
        push @$rules, $val->to_rule_array;
    }
}

1;

