# ABOUTME: Semantic handler for BNF pattern definitions (%NAME% = /regex/flags)
# ABOUTME: Builds compiled regex patterns from parse results
use 5.42.0;
use experimental qw(class);
use utf8;

class Chalk::BNF::PatternDef {
    field $name :param :reader;
    field $pattern :param :reader;  # Compiled regex

    # Semantic action: called when PatternDef rule completes
    # PatternDef -> PatternName '=' RegexLiteral
    # Receives the combined element from multiply operations
    sub from_element {
        my ($class, $element) = @_;
        # Element value should be array of children: [PatternName, '=', RegexLiteral]
        my $children = $element->value;
        return $element unless ref($children) eq 'ARRAY';

        # Extract children (skip whitespace/structural elements)
        my @parts = grep { defined $_ && $_ ne '=' } @$children;
        return $element unless @parts >= 2;

        my ($pattern_name_val, $regex_literal_val) = @parts;

        # Pattern name and regex are stored as handler objects or matched text
        my $name;
        my $body;
        my $flags = '';

        # Extract pattern name
        if (ref($pattern_name_val) && $pattern_name_val->can('name')) {
            $name = $pattern_name_val->name;
        } elsif ($pattern_name_val =~ /^%(\w+)%$/) {
            $name = $1;
        } else {
            return $element;  # Can't extract name
        }

        # Extract regex body and flags
        if (ref($regex_literal_val) && $regex_literal_val->can('body')) {
            $body = $regex_literal_val->body;
            $flags = $regex_literal_val->flags // '';
        } elsif ($regex_literal_val =~ m{^/((?:[^\\/]|\\.)*)/([\w]*)$}) {
            $body = $1;
            $flags = $2 // '';
        } else {
            return $element;  # Can't extract regex
        }

        # Compile the pattern
        my $compiled = qr/(?$flags:$body)/;

        return Chalk::BNF::PatternDef->new(
            name => $name,
            pattern => $compiled
        );
    }
}

