# ABOUTME: Semiring for parsing BNF files using semantic handler classes
# ABOUTME: Delegates to Chalk::BNF::* classes for semantic actions
use 5.42.0;
use experimental qw(class);
use utf8;
use Chalk::Base;

class Chalk::Semiring::BNFElement :isa(Chalk::Element) {
    field $value :param :reader;  # Can be any semantic value

    method add($other, $swap = undef) {
        # For BNF parsing, first successful parse wins
        return $self;
    }

    method multiply($other, $swap = undef) {
        # Sequential composition: accumulate children
        # If either is undefined/empty, return the other
        return $other unless defined $value;
        return $self unless defined $other->value;

        # Both have values: create array of children
        my @children = (
            (ref($value) eq 'ARRAY' ? $value->@* : $value),
            (ref($other->value) eq 'ARRAY' ? $other->value->@* : $other->value)
        );

        return Chalk::Semiring::BNFElement->new(value => \@children);
    }

    method equals($other, $swap = undef) {
        return 0 unless ref($other) eq ref($self);
        return $value == $other->value if ref($value) eq ref($other->value);
        return 0;
    }

    method score() { return 1; }

    method to_string(@) {
        return ref($value) ? ref($value) : ($value // 'undef');
    }
}

class Chalk::Semiring::BNF :isa(Chalk::Semiring) {
    field $mul_id :reader = Chalk::Semiring::BNFElement->new(value => undef);
    field $add_id :reader = Chalk::Semiring::BNFElement->new(value => undef);

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0, $matched_text = undef) {
        my $lhs = $rule->lhs;

        # For terminals with matched text, create appropriate handler
        if (defined $matched_text) {
            # Try to load and instantiate handler class
            my $handler_class = "Chalk::BNF::$lhs";

            eval "require $handler_class" or do {
                # No handler class, just store the matched text
                return Chalk::Semiring::BNFElement->new(value => $matched_text);
            };

            # Handler class exists, call from_matched_text if available
            if ($handler_class->can('from_matched_text')) {
                my $handler = $handler_class->from_matched_text($matched_text);
                return Chalk::Semiring::BNFElement->new(value => $handler);
            }

            # No from_matched_text method, just store text
            return Chalk::Semiring::BNFElement->new(value => $matched_text);
        }

        # Non-terminal: will be built from children via multiply/complete
        return Chalk::Semiring::BNFElement->new(value => undef);
    }

    # Called by Parser when a rule completes
    method on_rule_complete($rule, $element) {
        my $lhs = $rule->lhs;

        # Try to find handler class
        my $handler_class = "Chalk::BNF::$lhs";

        eval "require $handler_class" or do {
            # No handler class, return element as-is
            return $element;
        };

        # Handler exists, call from_element
        if ($handler_class->can('from_element')) {
            my $result = $handler_class->from_element($element);
            return Chalk::Semiring::BNFElement->new(value => $result);
        }

        # No from_element method, return as-is
        return $element;
    }
}

1;

