# ABOUTME: BNF file parser using Chalk parser with semantic handler classes
# ABOUTME: Dog-foods Chalk parser to parse BNF grammar files
package Chalk::Grammar::BNF;
use 5.42.0;
use utf8;
use Chalk::Grammar;
use Chalk::Parser;
use Chalk::Semiring::BNF;

# Hand-coded BNF meta-grammar
# This breaks the bootstrap cycle: meta-grammar is hand-coded in Perl,
# then used to parse BNF files which can define other grammars
my $bnf_meta_grammar = Chalk::Grammar->build_grammar(
    auto_insert => ['WS_OPT'],
    rules => [
        # Top level: file contains lines
        ['BNFFile' => ['LineList']],

        ['LineList' => []],  # Empty file
        ['LineList' => ['Line', 'LineList']],

        ['Line' => ['PatternDef']],
        ['Line' => ['GrammarRule']],
        ['Line' => ['Comment']],

        # Pattern definition: %NAME% = /pattern/flags
        ['PatternDef' => ['PatternName', '=', 'RegexLiteral']],
        ['PatternName' => [qr/%(\w+)%/]],
        ['RegexLiteral' => [qr{/((?:[^\\/]|\\.)*)/([\w]*)}]],

        # Grammar rule: LHS -> RHS
        ['GrammarRule' => ['Identifier', '->', 'RHS']],
        ['RHS' => ['TokenList']],
        ['RHS' => []],  # Empty RHS (epsilon rule)

        ['TokenList' => ['Token']],
        ['TokenList' => ['Token', 'TokenList']],

        ['Token' => ['Terminal']],
        ['Token' => ['PatternRef']],
        ['Token' => ['Identifier']],

        ['Terminal' => [qr/'([^']*)'/]],
        ['PatternRef' => [qr/%(\w+)%/]],
        ['Identifier' => [qr/([a-zA-Z_][\w:]*)/]],

        ['Comment' => [qr/#[^\n]*/]],

        # Whitespace handling
        ['WS_OPT' => []],
        ['WS_OPT' => ['WS']],
        ['WS_OPT' => ['WS', 'WS_OPT']],
        ['WS' => [qr/[ \t\n]+/]],
    ]
);

sub parse_bnf_string {
    my ($content) = @_;

    # Use BNF semiring with semantic handler classes
    my $semiring = Chalk::Semiring::BNF->new();
    my $parser = Chalk::Parser->new(
        grammar => $bnf_meta_grammar,
        semiring => $semiring
    );

    my $result = $parser->parse_string($content);

    unless ($result) {
        die "Failed to parse BNF content\n";
    }

    # Extract BNFFile object from result
    my $bnf_file = $result->value;

    unless ($bnf_file && $bnf_file->isa('Chalk::BNF::BNFFile')) {
        die "Parse result is not a BNFFile object\n";
    }

    # Return rules array (with pattern references resolved)
    return $bnf_file->get_rules();
}

