# ABOUTME: Semantic handler for BNF grammar rule (LHS -> RHS)
# ABOUTME: Builds grammar rule array from parsed components
use 5.42.0;
use experimental qw(class);
use utf8;
use Scalar::Util qw(blessed);

class Chalk::BNF::GrammarRule {
    field $lhs :param :reader;
    field $rhs :param :reader;  # Array of tokens

    # Called when GrammarRule completes
    # GrammarRule -> Identifier '->' RHS
    sub from_element($class, $element) {
        my $children = $element->value;
        return $element unless ref($children) eq 'ARRAY';

        # Extract LHS and RHS (skip '->' and whitespace)
        my @parts = grep { defined $_ && $_ ne '->' } @$children;
        return $element unless @parts >= 2;

        my ($lhs_val, $rhs_val) = @parts;

        # Extract LHS name
        my $lhs;
        if (blessed($lhs_val) && $lhs_val->can('name')) {
            $lhs = $lhs_val->name;
        } elsif (!ref($lhs_val)) {
            $lhs = $lhs_val;
        } else {
            return $element;  # Can't extract LHS
        }

        # Extract RHS tokens
        my @rhs_tokens;
        if (blessed($rhs_val) && $rhs_val->can('tokens')) {
            @rhs_tokens = $rhs_val->tokens;
        } elsif (ref($rhs_val) eq 'ARRAY') {
            @rhs_tokens = @$rhs_val;
        } else {
            # Empty RHS (epsilon rule)
            @rhs_tokens = ();
        }

        return Chalk::BNF::GrammarRule->new(
            lhs => $lhs,
            rhs => \@rhs_tokens
        );
    }

    # Convert to format expected by Chalk::Grammar::build_grammar
    method to_rule_array() {
        return [$lhs, $rhs];
    }
}

1;

