# ABOUTME: Semantic handler for BNF RHS (right-hand side of rule)
# ABOUTME: Collects tokens from TokenList
use 5.42.0;
use experimental qw(class);
use utf8;
use Scalar::Util qw(blessed);

class Chalk::BNF::RHS {
    field $tokens :param :reader = [];

    # Called when RHS completes
    # RHS -> TokenList
    # RHS -> (empty)
    sub from_element($class, $element) {
        my $children = $element->value;

        # Empty RHS
        return Chalk::BNF::RHS->new(tokens => []) unless defined $children;

        # Extract tokens from TokenList
        my @tokens;
        if (blessed($children) && $children->can('tokens')) {
            @tokens = $children->tokens;
        } elsif (ref($children) eq 'ARRAY') {
            # Flatten token list
            @tokens = Chalk::BNF::RHS::_flatten_tokens($children);
        }

        return Chalk::BNF::RHS->new(tokens => \@tokens);
    }
}

package Chalk::BNF::RHS {
sub _flatten_tokens($val) {
    my @result;

    if (ref($val) eq 'ARRAY') {
        for my $item (@$val) {
            push @result, Chalk::BNF::RHS::_flatten_tokens($item);
        }
    } elsif (blessed($val) && $val->can('value')) {
        push @result, $val->value;
    } elsif (blessed($val) && $val->can('name')) {
        push @result, $val->name;
    } elsif (!ref($val)) {
        push @result, $val;
    }

    return @result;
}
}

1;

