        no strict 'refs';
        $chalk_grammar = ${"${grammar_module}::chalk_grammar"};
    }

    # Verify grammar loaded
    if ( !defined($chalk_grammar) ) {
        die("Error: Grammar not loaded from module '$grammar_module'!\n");
    }

