     1→# ABOUTME: Grammar and rule definitions for Chalk parser
     2→# ABOUTME: Provides GrammarRule and Grammar classes for defining parsing grammars
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::GrammarRule {
     8→
     9→    # Supports both exact token matching and lexeme/regex patterns for terminals
    10→    # Use parse() for pre-tokenized input, parse_string() for lexeme matching
    11→    #
    12→    # TODO: Consider matrix-based Earley parsing optimization
    13→    # See: https://medium.com/@celine.y.lee/fast-earley-parsing-2216fb0909a3
    14→    # Matrix operations could optimize prediction/completion phases while
    15→    # lexemes handle terminal matching independently
    16→    use overload '""' => 'to_string';
    17→
    18→    state $next_id = 0;    # auto-incrementing rule ID
    19→    field $id  :reader = $next_id++;
    20→    field $lhs :param :reader;
    21→    field $rhs :param :reader;
    22→    field $probability :param :reader = 1.0;
    23→    field $nullable;
    24→
    25→    method is_right_recursive() { $lhs eq $rhs->[-1] }
    26→    method is_left_recursive()  { $lhs eq $rhs->[0] }
    27→
    28→    method is_nullable( $grammar, $seen = {} ) {
    29→        return $nullable if defined($nullable);    # memoize nullable
    30→
    31→        # Empty production is nullable
    32→        return $nullable = 1 if @$rhs == 0;
    33→
    34→        # All symbols in RHS must be nullable
    35→        return $nullable = 1 if all {
    36→            my @rules = $grammar->rules_for($_);
    37→
    38→            # Terminals (no rules) are not nullable
    39→            return 0 unless @rules;
    40→
    41→            # In cycle, assume not nullable
    42→            return 0 if $seen->{$_};
    43→
    44→            # Check if this symbol is nullable via any of its rules
    45→            $seen->{$_} = 1;
    46→            return 0 unless any { $_->is_nullable( $grammar, $seen ) } @rules;
    47→        } @$rhs;
    48→
    49→        return $nullable = 0;
    50→    }
    51→
    52→    method to_string(@) {
    53→        return "($id) $lhs -> " . join( ' ', $rhs->@* );
    54→    }
    55→
    56→    method terminal_to_regex($terminal) {
    57→        state %seen;
    58→
    59→        # Convert terminal to regex pattern
    60→        # If already a regex, return as-is
    61→        # If string literal, escape and convert to regex
    62→        return $seen{$terminal} //=
    63→          ref($terminal) eq 'Regexp' ? $terminal : qr/\Q$terminal\E/;
    64→    }
    65→}
    66→
    67→class Chalk::Grammar {
    68→    field $rules        :param :reader;
    69→    field $start_symbol :param :reader;
    70→    field %nullable_cache;
    71→    field %rules_waiting_for;  # Pre-computed: which rules can wait for which symbols
    72→
    73→    ADJUST {
    74→        for my $s ( keys(%$rules) ) {
    75→            $self->is_nullable($s);
    76→        }
    77→
    78→        # Pre-compute which rules can wait for which symbols
    79→        # For each rule A -> α B β, rule A can wait for symbol B
    80→        for my $lhs (keys %$rules) {
    81→            for my $rule (@{$rules->{$lhs}}) {
    82→                my @rhs = $rule->rhs->@*;
    83→                for my $i (0 .. $#rhs) {
    84→                    my $symbol = $rhs[$i];
    85→                    # This rule can have its dot before $symbol
    86→                    push @{$rules_waiting_for{$symbol} //= []}, {
    87→                        rule => $rule,
    88→                        dot_pos => $i,
    89→                    };
    90→                }
    91→            }
    92→        }
    93→    }
    94→
    95→    my sub new_rule( $lhs, $rhs, $probability = 1.0 ) {
    96→        $probability ||= 0.1;
    97→        return Chalk::GrammarRule->new(
    98→            lhs         => $lhs,
    99→            rhs         => $rhs,
   100→            probability => $probability
   101→        );
   102→    }
   103→
   104→    my sub insert ( $items, @list ) {
   105→        return [ ( map { $_, @$items } @list[ 0 .. $#list - 1 ] ), $list[-1] ];
   106→    }
   107→
   108→    sub build_grammar( $class, %args ) {
   109→        my $auto_insert = $args{auto_insert} // [];
   110→        my $rules_array = $args{rules} // [];
   111→
   112→        my %rules = ();
   113→        for my $r (@$rules_array) {
   114→            my ( $lhs, $rhs ) = @$r;
   115→            if ( @$auto_insert && @$rhs > 1 ) {
   116→                $r->[1] = insert( $auto_insert, @$rhs );
   117→            }
   118→            push( @{ $rules{$lhs} //= [] }, new_rule(@$r) );
   119→        }
   120→        return Chalk::Grammar->new( rules => \%rules, start_symbol => $rules_array->[0]->[0] );
   121→    }
   122→
   123→    method start_rule() { return $rules->{$start_symbol}->[0] }
   124→
   125→    method rules_for($symbol) {
   126→        return $rules->{$symbol}->@* if exists( $rules->{$symbol} );
   127→        return;
   128→    }
   129→
   130→    method is_nonterminal($symbol) {
   131→        return exists( $rules->{$symbol} );
   132→    }
   133→
   134→    method is_nullable($symbol) {
   135→
   136→        # Check cache first
   137→        return $nullable_cache{$symbol} if exists( $nullable_cache{$symbol} );
   138→
   139→       # Compute nullability by checking if any rule for this symbol is nullable
   140→        my $result = 0;
   141→        for my $rule ( $self->rules_for($symbol) ) {
   142→            if ( $rule->is_nullable($self) ) {
   143→                $result = 1;
   144→                last;
   145→            }
   146→        }
   147→
   148→        # Cache the result
   149→        $nullable_cache{$symbol} = $result;
   150→        return $result;
   151→    }
   152→
   153→    method rules_waiting_for($symbol) {
   154→        # Returns list of { rule, dot_pos } that can wait for this symbol
   155→        return $rules_waiting_for{$symbol}->@* if exists($rules_waiting_for{$symbol});
   156→        return;
   157→    }
   158→
   159→    method to_string(@) {
   160→        my $grammar = '';
   161→        $grammar .= "Grammar:\n";
   162→        for my $nt ( sort( keys( $rules->%* ) ) ) {
   163→            for my $rule ( $rules->{$nt}->@* ) {
   164→                $grammar .= "  $rule\n";
   165→            }
