     2→# ABOUTME: Avoids complex nested structures for bootstrap self-hosting
     3→package Chalk::BNF;
     4→use 5.42.0;
     5→use utf8;
     6→use Chalk::Grammar;
     7→
     8→sub parse_bnf_file($filename) {
     9→    open my $fh, '<:utf8', $filename or die "Cannot open $filename: $!";
    10→    my $content = do { local $/; <$fh> };
    11→    close $fh;
    12→
    13→    return parse_bnf_string($content);
    14→}
    15→
    16→sub build_chalk_grammar($bnf_content, $start_symbol = undef) {
    17→    my $rules = parse_bnf_string($bnf_content);
    18→
    19→    # If start symbol specified, ensure it's first
    20→    if (defined $start_symbol) {
    21→        my @ordered_rules = (
    22→            (grep { $_->[0] eq $start_symbol } @$rules),
    23→            (grep { $_->[0] ne $start_symbol } @$rules)
    24→        );
    25→        $rules = \@ordered_rules;
    26→    }
    27→
    28→    return Chalk::Grammar->build_grammar(rules => $rules);
    29→}
    30→
    31→sub parse_bnf_string($content) {
    32→    my %patterns;
    33→    my @rules;
    34→
    35→    my @lines = split /\n/, $content;
    36→    for my $line (@lines) {
    37→        $line = trim($line);
    38→
    39→        # Skip blank lines
    40→        next if $line eq '';
    41→
    42→        # Pattern definition: %NAME% = /regex/flags
    43→        # Must match before comment stripping since patterns may contain #
